(function() {
  const apiUrl = "https://api.lever.co/v0/postings/spotify?mode=json";
  const render = (payload) => {
    const pre = document.createElement("pre");
    pre.id = "spotify-jobs";
    pre.textContent = JSON.stringify(payload);
    document.body.innerHTML = "";
    document.body.appendChild(pre);
  };
  fetch(apiUrl)
    .then((res) => res.json())
    .then((data) => {
      render({ jobs: data, __source_url: window.location.href });
    })
    .catch((err) => {
      render({ jobs: [], error: String(err), __source_url: window.location.href });
    });
})();

